366	// TestSimulateScheduleDifferential compares the event-driven simulation
367	// against an independent tick-by-tick reference implementation.
368	func TestSimulateScheduleDifferential(t *testing.T) {
369		seed := time.Now().UnixNano()
370		rng := rand.New(rand.NewSource(seed))
371		for iter := 0; iter < 2000; iter++ {
372			n := 1 + rng.Intn(8)
373			horizon := int64(1 + rng.Intn(40))
374			tasks := make([]scheduledTask, n)
375			ids := map[string]bool{}
376			for i := 0; i < n; i++ {
377				var id string
378				for {
379					id = "t" + strconv.Itoa(rng.Intn(20))
380					if !ids[id] {
381						ids[id] = true
382						break
383					}
384				}
385				tasks[i] = scheduledTask{
386					id:        id,
387					priority:  int64(rng.Intn(4)),
388					release:   int64(rng.Intn(int(horizon))),
389					execution: int64(1 + rng.Intn(15)),
390					deadline:  int64(0),
391				}
392				if rng.Intn(2) == 0 {
393					tasks[i].deadline = tasks[i].release + int64(1+rng.Intn(30))
394				} else {
395					tasks[i].deadline = tasks[i].release + int64(1+rng.Intn(3))
396				}
397			}
398	
399			got := simulateSchedule(tasks, horizon)
400	
401			// Independent tick-by-tick model.
402			remaining := make([]int64, n)
403			for i, tk := range tasks {
404				remaining[i] = tk.execution
405			}
406			var refSegs []executionSegment
407			completion := make([]*int64, n)
408			current := -1
409			for now := int64(0); now < horizon; now++ {
410				best := -1
411				for i := 0; i < n; i++ {
412					if tasks[i].release > now || remaining[i] == 0 {
413						continue
414					}
415					if best == -1 {
416						best = i
417						continue
418					}
419					a, b := tasks[i], tasks[best]
420					if a.priority < b.priority ||
421						(a.priority == b.priority && a.release < b.release) ||
422						(a.priority == b.priority && a.release == b.release && i < best) {
423						best = i
424					}
425				}
426				if current >= 0 && remaining[current] == 0 {
427					current = -1
428				}
429				if best != -1 && (current == -1 || tasks[best].priority < tasks[current].priority) {
430					current = best
431				}
432				if current == -1 {
433					continue
434				}
435				remaining[current]--
436				last := len(refSegs) - 1
437				if last >= 0 && refSegs[last].index == current && refSegs[last].end == now {
438					refSegs[last].end = now + 1
439				} else {
440					refSegs = append(refSegs, executionSegment{index: current, start: now, end: now + 1})
441				}
442				if remaining[current] == 0 {
443					done := now + 1
444					completion[current] = &done
445					current = -1
446				}
447			}
448	
449			if len(got.Timeline) != len(refSegs) {
450				t.Fatalf("iter %d (seed %d): interval count %d != %d; got %+v",
451					iter, seed, len(got.Timeline), len(refSegs), got.Timeline)
452			}
453			for k, seg := range refSegs {
454				want := timelineInterval{TaskID: tasks[seg.index].id, Start: seg.start, End: seg.end}
455				if got.Timeline[k] != want {
456					t.Fatalf("iter %d (seed %d): interval %d got %+v, want %+v",
457						iter, seed, k, got.Timeline[k], want)
458				}
459			}
460			for i, tk := range tasks {
461				executed := tk.execution - remaining[i]
462				if got.Results[i].Executed != executed {
463					t.Fatalf("iter %d (seed %d): task %d executed got %d want %d",
464						iter, seed, i, got.Results[i].Executed, executed)
465				}
466				if got.Results[i].Remaining != remaining[i] {
467					t.Fatalf("iter %d (seed %d): task %d remaining got %d want %d",
468						iter, seed, i, got.Results[i].Remaining, remaining[i])
469				}
470				if (got.Results[i].Completion == nil) != (completion[i] == nil) ||
471					(got.Results[i].Completion != nil && *got.Results[i].Completion != *completion[i]) {
472					t.Fatalf("iter %d (seed %d): task %d completion got %v want %v",
473						iter, seed, i, got.Results[i].Completion, completion[i])
474				}
475				var wantStatus string
476				switch c := completion[i]; {
477				case c != nil && *c <= tk.deadline:
478					wantStatus = "met"
479				case c != nil:
480					wantStatus = "missed"
481				case tk.deadline <= horizon:
482					wantStatus = "missed"
483				default:
484					wantStatus = "pending"
485				}
486				if got.Results[i].DeadlineStatus != wantStatus {
487					t.Fatalf("iter %d (seed %d): task %d status got %q want %q",
488						iter, seed, i, got.Results[i].DeadlineStatus, wantStatus)
